namespace sv_3f60ad73538f4d7eb7d8619e3e60de62.Services;

public record WarehouseInfo(string Id, string Name)
{
    public static readonly WarehouseInfo[] All =
    [
        new("WH-A", "Warehouse A"),
        new("WH-B", "Warehouse B"),
        new("WH-C", "Warehouse C"),
    ];

    public static WarehouseInfo Default => All[0];
}

namespace sv_3f60ad73538f4d7eb7d8619e3e60de62.Services;

/// <summary>
/// Scoped service (per-circuit) that tracks low-stock alert counts for a warehouse.
/// Components subscribe to <see cref="OnChange"/> and call <see cref="StartPolling"/>
/// / <see cref="StopPolling"/> to control the background refresh cycle.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    /// <summary>Raised on the thread-pool — subscribers must wrap StateHasChanged in InvokeAsync.</summary>
    public event Action? OnChange;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begins polling every 10 seconds for the given warehouse.
    /// Multiple callers are ref-counted; polling runs while at least one subscriber is active.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;
        if (_subscriberCount > 1)
            return; // already polling

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    /// <summary>Decrements the subscriber count; stops polling when it reaches zero.</summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
            CancelPolling();
    }

    /// <summary>
    /// Restarts polling for a different warehouse (e.g. after the user switches warehouses).
    /// </summary>
    public void RestartPolling(string warehouseId)
    {
        if (_subscriberCount == 0)
            return;

        CancelPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        // Fetch immediately on start, then every tick.
        await FetchAndNotifyAsync(warehouseId);

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (!await _timer!.WaitForNextTickAsync(ct))
                    break;

                await FetchAndNotifyAsync(warehouseId);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAndNotifyAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose() => CancelPolling();
}

