@page "/dashboard"
@rendermode InteractiveServer
@using sv_3f60ad73538f4d7eb7d8619e3e60de62.Services
@inject InventoryAlertService Alerts
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<p>
    Currently viewing: <strong>@Warehouse?.Name</strong>
</p>

<div class="card" style="max-width: 24rem;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            @if (Alerts.CurrentAlertCount > 0)
            {
                <span class="text-danger">@Alerts.CurrentAlertCount</span>
            }
            else
            {
                <span class="text-success">0</span>
            }
        </p>
        <p class="text-muted">Refreshes every 10 seconds</p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private string _activeWarehouseId = string.Empty;
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        Alerts.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        var currentId = Warehouse?.Id ?? WarehouseInfo.Default.Id;

        if (_activeWarehouseId == currentId)
            return;

        // First visit or warehouse changed — (re)start polling for the new warehouse.
        if (_activeWarehouseId != string.Empty)
            Alerts.RestartPolling(currentId);
        else
            Alerts.StartPolling(currentId);

        _activeWarehouseId = currentId;
    }

    public void Dispose()
    {
        Alerts.OnChange -= _handler;
        Alerts.StopPolling();
    }
}

